3. 使用websocket实时获取TDengine中设备最新数据：

```
<template>
  <div>
    <v-chart :options="chartData"></v-chart>
  </div>
</template>

<script>
import { VueECharts } from 'vue-echarts'

export default {
  components: {
    'v-chart': VueECharts
  },
  data() {
    return {
      chartData: {
        title: {
          text: '设备最新数据'
        },
        tooltip: {
          trigger: 'axis',
          axisPointer: {
            animation: false
          }
        },
        xAxis: {
          type: 'category',
          boundaryGap: false,
          data: []
        },
        yAxis: {
          type: 'value',
          boundaryGap: [0, '100%']
        },
        series: [{
          name: '最新数据',
          type: 'line',
          data: []
        }]
      }
    }
  },
  mounted() {
    const ws = new WebSocket('ws://localhost:8080')
    ws.onopen = () => {
      console.log('WebSocket connected.')
    }
    ws.onmessage = event => {
      const data = JSON.parse(event.data)
      const time = new Date(data.time).toLocaleTimeString()
      const value = data.value
      this.chartData.xAxis.data.push(time)
      this.chartData.series[0].data.push(value)
      this.$refs.chart.update()
    }
    ws.onerror = event => {
      console.log('WebSocket error:', event)
    }
    ws.onclose = event => {
      console.log('WebSocket closed:', event)
    }
  }
}
</script>
```

