def check_prime(n):

    """ function to check if n is prime"""

    # check if a number is less than 2 
    # (the smallest prime number is 2)
    if n < 2:
        return False

    # check for divisibility up to the square root of n
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False

    return True


def check_product_prime(numbers):

    """ function to check if product of a list is prime"""

    # initial product is 1
    product = 1

    # multiply all numbers in the list
    for num in numbers:
        product *= num

    return check_prime(product)


